from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    if old not in text:
        raise RuntimeError(f"expected patch anchor missing in {path}: {old[:120]!r}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


def append_once(path: str, marker: str, content: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    if marker not in text:
        target.write_text(text.rstrip() + "\n\n" + content.strip() + "\n", encoding="utf-8")


def main() -> None:
    write('source/src/wls/cognition.py', 'from __future__ import annotations\n\nfrom dataclasses import asdict, dataclass, field\nfrom pathlib import Path\nfrom typing import Any\nimport json\nimport re\n\nfrom .config import RuntimeConfig\nfrom .db import Database\nfrom .evidence import EvidenceLedger\nfrom .schemas import Plan, RiskLevel, digest_json, new_id, utc_now\nfrom .temporal_world import TemporalCausalWorld\nfrom .text import tokens\n\n\nTEXT_SUFFIXES = {\n    ".txt", ".md", ".json", ".yaml", ".yml", ".toml", ".py", ".js", ".ts",\n    ".ps1", ".bat", ".sh", ".ini", ".cfg", ".csv", ".log", ".tex",\n}\n\n\n@dataclass(slots=True)\nclass HypothesisCandidate:\n    key: str\n    subject: str\n    claim: str\n    rationale: str\n    base_score: float\n    actions: list[dict[str, Any]] = field(default_factory=list)\n    support_ids: list[str] = field(default_factory=list)\n    opposing_ids: list[str] = field(default_factory=list)\n    memory_ids: list[str] = field(default_factory=list)\n    fact_ids: list[str] = field(default_factory=list)\n    goal_id: str | None = None\n    cause_predicate: str = "evidence_present"\n    score: float = 0.0\n\n    def to_dict(self) -> dict[str, Any]:\n        return asdict(self)\n\n\ndef ensure_cognition_tables(db: Database) -> None:\n    statements = [\n        """\n        CREATE TABLE IF NOT EXISTS cognitive_traces (\n            trace_id TEXT PRIMARY KEY,\n            cycle_id TEXT NOT NULL UNIQUE,\n            provider TEXT NOT NULL,\n            context_sha256 TEXT NOT NULL,\n            selected_hypothesis_id TEXT,\n            selected_key TEXT NOT NULL,\n            counterfactual_key TEXT NOT NULL,\n            memory_changed_decision INTEGER NOT NULL,\n            memory_delta REAL NOT NULL,\n            plan_id TEXT,\n            status TEXT NOT NULL,\n            decomposition_json TEXT NOT NULL,\n            alternatives_json TEXT NOT NULL,\n            outcome_json TEXT,\n            created_at TEXT NOT NULL,\n            resolved_at TEXT\n        )\n        """,\n        """\n        CREATE TABLE IF NOT EXISTS cognitive_hypotheses (\n            hypothesis_id TEXT PRIMARY KEY,\n            trace_id TEXT NOT NULL,\n            cycle_id TEXT NOT NULL,\n            hypothesis_key TEXT NOT NULL,\n            subject TEXT NOT NULL,\n            claim TEXT NOT NULL,\n            rationale TEXT NOT NULL,\n            score REAL NOT NULL,\n            selected INTEGER NOT NULL,\n            support_ids_json TEXT NOT NULL,\n            opposing_ids_json TEXT NOT NULL,\n            memory_ids_json TEXT NOT NULL,\n            fact_ids_json TEXT NOT NULL,\n            actions_json TEXT NOT NULL,\n            temporal_json TEXT NOT NULL,\n            created_at TEXT NOT NULL,\n            FOREIGN KEY(trace_id) REFERENCES cognitive_traces(trace_id)\n        )\n        """,\n        """\n        CREATE INDEX IF NOT EXISTS idx_cognitive_hypotheses_cycle\n        ON cognitive_hypotheses(cycle_id, score DESC)\n        """,\n        """\n        CREATE TABLE IF NOT EXISTS cognitive_predictions (\n            prediction_id TEXT PRIMARY KEY,\n            trace_id TEXT NOT NULL,\n            hypothesis_id TEXT NOT NULL,\n            action_index INTEGER NOT NULL,\n            expected_json TEXT NOT NULL,\n            confidence REAL NOT NULL,\n            status TEXT NOT NULL,\n            actual_json TEXT,\n            created_at TEXT NOT NULL,\n            resolved_at TEXT,\n            FOREIGN KEY(trace_id) REFERENCES cognitive_traces(trace_id),\n            FOREIGN KEY(hypothesis_id) REFERENCES cognitive_hypotheses(hypothesis_id)\n        )\n        """,\n        """\n        CREATE INDEX IF NOT EXISTS idx_cognitive_predictions_trace\n        ON cognitive_predictions(trace_id, status)\n        """,\n    ]\n    with db.transaction() as connection:\n        for statement in statements:\n            connection.execute(statement)\n\n\nclass CognitiveEngine:\n    """Evidence-bound local hypothesis competition and outcome calibration."""\n\n    def __init__(\n        self,\n        db: Database,\n        ledger: EvidenceLedger,\n        temporal_world: TemporalCausalWorld,\n        config: RuntimeConfig,\n    ) -> None:\n        self.db = db\n        self.ledger = ledger\n        self.temporal_world = temporal_world\n        self.config = config\n        ensure_cognition_tables(db)\n\n    @property\n    def minimum_confidence(self) -> float:\n        value = float(self.config.provider.get("cognitive_min_confidence", 0.52))\n        return max(0.0, min(1.0, value))\n\n    @property\n    def maximum_hypotheses(self) -> int:\n        value = int(self.config.provider.get("cognitive_max_hypotheses", 6))\n        return max(2, min(20, value))\n\n    def create_plan(self, context: dict[str, Any]) -> dict[str, Any]:\n        cycle_id = str(context.get("cycle_id") or new_id("cycle"))\n        actual = self._rank(context, include_memories=True)\n        counterfactual = self._rank(context, include_memories=False)\n        selected = actual[0]\n        counter_selected = counterfactual[0]\n        max_actions = max(0, int(context.get("budget", {}).get("max_actions", 0)))\n        actions = selected.actions[:max_actions]\n        if selected.score < self.minimum_confidence:\n            actions = [self._noop("No hypothesis crossed the evidence threshold", selected.goal_id)][:max_actions]\n\n        trace_id = new_id("cogtrace")\n        now = utc_now()\n        memory_free_score = self._score(selected, context, include_memories=False)\n        memory_delta = selected.score - memory_free_score\n        memory_changed = selected.key != counter_selected.key\n        alternatives = [\n            {\n                "key": item.key,\n                "claim": item.claim,\n                "score": round(item.score, 6),\n                "action_tools": [action["tool"] for action in item.actions],\n                "support_ids": item.support_ids,\n            }\n            for item in actual[1 : self.maximum_hypotheses]\n        ]\n        decomposition = self._decomposition(selected, actions)\n        with self.db.transaction() as connection:\n            connection.execute(\n                """\n                INSERT INTO cognitive_traces(\n                    trace_id,cycle_id,provider,context_sha256,selected_hypothesis_id,\n                    selected_key,counterfactual_key,memory_changed_decision,memory_delta,\n                    plan_id,status,decomposition_json,alternatives_json,outcome_json,\n                    created_at,resolved_at\n                ) VALUES (?,?,?,?,NULL,?,?,?,?,NULL,\'DELIBERATED\',?,?,NULL,?,NULL)\n                """,\n                (\n                    trace_id,\n                    cycle_id,\n                    "bounded_cognitive",\n                    digest_json(self._digest_context(context)),\n                    selected.key,\n                    counter_selected.key,\n                    int(memory_changed),\n                    memory_delta,\n                    json.dumps(decomposition, ensure_ascii=False, sort_keys=True),\n                    json.dumps(alternatives, ensure_ascii=False, sort_keys=True),\n                    now,\n                ),\n            )\n\n        selected_id: str | None = None\n        for index, candidate in enumerate(actual[: self.maximum_hypotheses]):\n            temporal = self._temporalize(candidate, cycle_id) if index == 0 and candidate.support_ids else {}\n            hypothesis_id = new_id("hyp")\n            with self.db.transaction() as connection:\n                connection.execute(\n                    """\n                    INSERT INTO cognitive_hypotheses(\n                        hypothesis_id,trace_id,cycle_id,hypothesis_key,subject,claim,\n                        rationale,score,selected,support_ids_json,opposing_ids_json,\n                        memory_ids_json,fact_ids_json,actions_json,temporal_json,created_at\n                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)\n                    """,\n                    (\n                        hypothesis_id,\n                        trace_id,\n                        cycle_id,\n                        candidate.key,\n                        candidate.subject,\n                        candidate.claim,\n                        candidate.rationale,\n                        candidate.score,\n                        int(index == 0),\n                        json.dumps(candidate.support_ids, ensure_ascii=False),\n                        json.dumps(candidate.opposing_ids, ensure_ascii=False),\n                        json.dumps(candidate.memory_ids, ensure_ascii=False),\n                        json.dumps(candidate.fact_ids, ensure_ascii=False),\n                        json.dumps(candidate.actions, ensure_ascii=False, sort_keys=True),\n                        json.dumps(temporal, ensure_ascii=False, sort_keys=True),\n                        now,\n                    ),\n                )\n            if index == 0:\n                selected_id = hypothesis_id\n                self._create_predictions(trace_id, hypothesis_id, actions, candidate.score, now)\n\n        with self.db.transaction() as connection:\n            connection.execute(\n                "UPDATE cognitive_traces SET selected_hypothesis_id=? WHERE trace_id=?",\n                (selected_id, trace_id),\n            )\n            self.ledger.append(\n                "cognitive_deliberation_completed",\n                {\n                    "trace_id": trace_id,\n                    "cycle_id": cycle_id,\n                    "selected_key": selected.key,\n                    "selected_score": selected.score,\n                    "counterfactual_key": counter_selected.key,\n                    "memory_changed_decision": memory_changed,\n                    "memory_delta": memory_delta,\n                    "alternatives": alternatives,\n                },\n                connection,\n            )\n        return {\n            "rationale": (\n                f"Bounded local cognition selected \'{selected.claim}\' at confidence "\n                f"{selected.score:.3f}; the memory-free counterfactual selected "\n                f"\'{counter_selected.claim}\'."\n            ),\n            "actions": actions,\n            "memory_ids": list(dict.fromkeys(selected.memory_ids)),\n            "world_fact_ids": list(dict.fromkeys(selected.fact_ids)),\n            "unknowns": list(dict.fromkeys([\n                *[str(item) for item in context.get("unknowns", [])],\n                *([f"hypothesis_below_threshold:{selected.key}"] if selected.score < self.minimum_confidence else []),\n            ])),\n        }\n\n    def attach_plan(self, cycle_id: str, plan: Plan) -> None:\n        with self.db.transaction() as connection:\n            updated = connection.execute(\n                "UPDATE cognitive_traces SET plan_id=?,status=\'PLANNED\' WHERE cycle_id=? AND plan_id IS NULL",\n                (plan.plan_id, cycle_id),\n            ).rowcount\n            if updated:\n                self.ledger.append(\n                    "cognitive_plan_attached",\n                    {"cycle_id": cycle_id, "plan_id": plan.plan_id},\n                    connection,\n                )\n\n    def resolve_cycle(\n        self,\n        cycle_id: str,\n        plan: Plan,\n        outcomes: list[dict[str, Any]],\n    ) -> dict[str, Any] | None:\n        trace = self.db.query_one("SELECT * FROM cognitive_traces WHERE cycle_id=?", (cycle_id,))\n        if trace is None:\n            return None\n        predictions = self.db.query_all(\n            "SELECT * FROM cognitive_predictions WHERE trace_id=? AND status=\'OPEN\' ORDER BY action_index",\n            (trace["trace_id"],),\n        )\n        outcome_by_action = {\n            str(item.get("action_id")): item\n            for item in outcomes\n            if item.get("action_id")\n        }\n        resolved: list[dict[str, Any]] = []\n        successes: list[bool] = []\n        actual: dict[str, Any]\n        for row in predictions:\n            index = int(row["action_index"])\n            if index >= len(plan.actions):\n                status = "UNKNOWN"\n                actual = {"reason": "planned action index missing"}\n            else:\n                action = plan.actions[index]\n                outcome = outcome_by_action.get(action.action_id)\n                if outcome is None:\n                    status = "UNKNOWN"\n                    actual = {"reason": "no outcome", "action_id": action.action_id}\n                else:\n                    success = bool(outcome.get("success"))\n                    successes.append(success)\n                    status = "CONFIRMED" if success else "REFUTED"\n                    actual = {\n                        "action_id": action.action_id,\n                        "tool": action.tool,\n                        "success": success,\n                        "status": outcome.get("status"),\n                        "evaluation": outcome.get("evaluation", {}),\n                    }\n            with self.db.transaction() as connection:\n                connection.execute(\n                    "UPDATE cognitive_predictions SET status=?,actual_json=?,resolved_at=? WHERE prediction_id=?",\n                    (status, json.dumps(actual, ensure_ascii=False, sort_keys=True), utc_now(), row["prediction_id"]),\n                )\n            resolved.append({"prediction_id": row["prediction_id"], "status": status, "actual": actual})\n\n        calibration = self._calibrate(trace, successes, plan, outcomes)\n        outcome_record = {\n            "predictions": resolved,\n            "calibration": calibration,\n            "successful_actions": sum(successes),\n            "observed_actions": len(successes),\n        }\n        with self.db.transaction() as connection:\n            connection.execute(\n                "UPDATE cognitive_traces SET status=\'RESOLVED\',outcome_json=?,resolved_at=? WHERE trace_id=?",\n                (json.dumps(outcome_record, ensure_ascii=False, sort_keys=True), utc_now(), trace["trace_id"]),\n            )\n            self.ledger.append(\n                "cognitive_trace_resolved",\n                {"trace_id": trace["trace_id"], "cycle_id": cycle_id, "plan_id": plan.plan_id, "outcome": outcome_record},\n                connection,\n            )\n        return {\n            "trace_id": trace["trace_id"],\n            "selected_key": trace["selected_key"],\n            "memory_changed_decision": bool(trace["memory_changed_decision"]),\n            **outcome_record,\n        }\n\n    def recent(self, limit: int = 20) -> list[dict[str, Any]]:\n        rows = self.db.query_all(\n            "SELECT * FROM cognitive_traces ORDER BY created_at DESC LIMIT ?",\n            (max(1, min(200, int(limit))),),\n        )\n        return [\n            {\n                "trace_id": row["trace_id"],\n                "cycle_id": row["cycle_id"],\n                "selected_key": row["selected_key"],\n                "counterfactual_key": row["counterfactual_key"],\n                "memory_changed_decision": bool(row["memory_changed_decision"]),\n                "memory_delta": float(row["memory_delta"]),\n                "plan_id": row["plan_id"],\n                "status": row["status"],\n                "decomposition": json.loads(row["decomposition_json"]),\n                "alternatives": json.loads(row["alternatives_json"]),\n                "outcome": json.loads(row["outcome_json"]) if row["outcome_json"] else None,\n                "created_at": row["created_at"],\n                "resolved_at": row["resolved_at"],\n            }\n            for row in rows\n        ]\n\n    def summary(self, limit: int = 500) -> dict[str, Any]:\n        rows = self.db.query_all(\n            "SELECT status,memory_changed_decision,memory_delta,outcome_json FROM cognitive_traces ORDER BY created_at DESC LIMIT ?",\n            (max(1, min(5000, int(limit))),),\n        )\n        prediction_counts = {"confirmed": 0, "refuted": 0, "unknown": 0}\n        for row in rows:\n            outcome = json.loads(row["outcome_json"] or "{}")\n            for item in outcome.get("predictions", []):\n                key = str(item.get("status", "UNKNOWN")).lower()\n                if key in prediction_counts:\n                    prediction_counts[key] += 1\n        memory_changed = sum(bool(row["memory_changed_decision"]) for row in rows)\n        return {\n            "traces": len(rows),\n            "resolved": sum(row["status"] == "RESOLVED" for row in rows),\n            "memory_changed_decisions": memory_changed,\n            "memory_change_rate": memory_changed / len(rows) if rows else 0.0,\n            "mean_memory_delta": sum(float(row["memory_delta"]) for row in rows) / len(rows) if rows else 0.0,\n            "predictions": prediction_counts,\n        }\n\n    def integrity(self) -> tuple[bool, dict[str, int]]:\n        checks = {\n            "orphan_hypotheses": """\n                SELECT COUNT(*) AS n FROM cognitive_hypotheses h\n                LEFT JOIN cognitive_traces t ON t.trace_id=h.trace_id\n                WHERE t.trace_id IS NULL\n            """,\n            "orphan_predictions": """\n                SELECT COUNT(*) AS n FROM cognitive_predictions p\n                LEFT JOIN cognitive_traces t ON t.trace_id=p.trace_id\n                LEFT JOIN cognitive_hypotheses h ON h.hypothesis_id=p.hypothesis_id\n                WHERE t.trace_id IS NULL OR h.hypothesis_id IS NULL\n            """,\n            "resolved_without_outcome": """\n                SELECT COUNT(*) AS n FROM cognitive_traces\n                WHERE status=\'RESOLVED\' AND outcome_json IS NULL\n            """,\n        }\n        counts: dict[str, int] = {}\n        for name, sql in checks.items():\n            row = self.db.query_one(sql)\n            counts[name] = int(row["n"]) if row else 0\n        return all(value == 0 for value in counts.values()), counts\n\n    def _rank(self, context: dict[str, Any], *, include_memories: bool) -> list[HypothesisCandidate]:\n        candidates = self._candidates(context, include_memories=include_memories)\n        for candidate in candidates:\n            candidate.score = self._score(candidate, context, include_memories=include_memories)\n            if not include_memories:\n                candidate.memory_ids = []\n        unique: dict[str, HypothesisCandidate] = {}\n        for candidate in candidates:\n            previous = unique.get(candidate.key)\n            if previous is None or candidate.score > previous.score:\n                unique[candidate.key] = candidate\n        return sorted(unique.values(), key=lambda item: (item.score, item.key), reverse=True)[: self.maximum_hypotheses]\n\n    def _candidates(\n        self, context: dict[str, Any], *, include_memories: bool\n    ) -> list[HypothesisCandidate]:\n        candidates: list[HypothesisCandidate] = []\n        for item in context.get("workspace", []):\n            if item.get("item_type") != "event":\n                continue\n            event_id = str(item.get("reference_id", ""))\n            event = item.get("payload", {})\n            observation = event.get("payload", {}).get("observation", {})\n            if not isinstance(observation, dict):\n                continue\n            kind = str(observation.get("kind", ""))\n            subject = str(observation.get("subject", "") or "unknown")\n            predicate = str(observation.get("predicate", "") or kind or "state")\n            value = observation.get("value")\n            confidence = float(observation.get("confidence", 0.5))\n            support = [str(value) for value in (event_id, observation.get("observation_id")) if value]\n            goal_id = self._best_goal_id(context, f"{subject} {predicate} {value}")\n            if kind == "filesystem_change" and value in {"created", "modified"} and Path(subject).suffix.lower() in TEXT_SUFFIXES:\n                candidates.append(HypothesisCandidate(\n                    key=f"inspect_changed_text:{subject}", subject=subject,\n                    claim="A changed text artifact should be inspected before any response.",\n                    rationale="Direct filesystem evidence identifies a bounded readable artifact.",\n                    base_score=0.70 + 0.20 * confidence,\n                    actions=[self._action("read_file", {"path": subject, "max_bytes": 524288}, "Inspect the observed changed text artifact", "File content or bounded binary preview", ["output contains path", "output contains text or binary marker"], goal_id)],\n                    support_ids=support, goal_id=goal_id, cause_predicate=predicate,\n                ))\n            elif kind == "external_event" and isinstance(value, dict) and value.get("action") == "inspect_path":\n                target = str(value.get("path", ""))\n                if target:\n                    candidates.append(HypothesisCandidate(\n                        key=f"inspect_requested_path:{target}", subject=target,\n                        claim="The explicit human path request should be inspected read-only.",\n                        rationale="A direct external request supplies the target and allowed read intent.",\n                        base_score=0.94,\n                        actions=[self._action("list_directory", {"path": target, "limit": 200}, "Inspect the explicitly requested path", "Bounded directory listing", ["output contains items"], goal_id)],\n                        support_ids=support, goal_id=goal_id, cause_predicate=predicate,\n                    ))\n            elif kind in {"sensor_error", "service_health", "process_change"}:\n                outbox = Path(str(context.get("paths", {}).get("outbox", ".")))\n                note_path = outbox / f"cognition-{event_id or digest_json(observation)[:12]}.json"\n                candidates.append(HypothesisCandidate(\n                    key=f"preserve_attention:{kind}:{subject}", subject=subject,\n                    claim=f"The observed {kind} requires evidence preservation before repair.",\n                    rationale="The observation may affect continuity, but repair authority is not implied.",\n                    base_score=0.62 + 0.20 * confidence,\n                    actions=[self._action("emit_note", {"path": str(note_path), "title": f"WLS cognitive attention: {kind}", "body": json.dumps(observation, ensure_ascii=False, sort_keys=True)[:4000]}, "Preserve the observed anomaly for later diagnosis", "Internal evidence note written to the WLS outbox", ["output contains path"], goal_id)],\n                    support_ids=support, goal_id=goal_id, cause_predicate=predicate,\n                ))\n            else:\n                candidates.append(HypothesisCandidate(\n                    key=f"defer_unsupported_event:{kind}:{subject}", subject=subject,\n                    claim="The current event does not justify a concrete external action.",\n                    rationale="Evidence is retained while unsupported action is withheld.",\n                    base_score=0.42 + 0.15 * confidence,\n                    actions=[self._noop("Unsupported event remains explicit", goal_id)],\n                    support_ids=support, goal_id=goal_id, cause_predicate=predicate,\n                ))\n\n        if include_memories:\n            for memory in context.get("memories", []):\n                if str(memory.get("memory_type")) != "procedural":\n                    continue\n                if float(memory.get("confidence", 0.0)) < 0.9:\n                    continue\n                content = memory.get("content", {})\n                rule = content.get("decision_rule") if isinstance(content, dict) else None\n                if not isinstance(rule, dict):\n                    continue\n                candidate_id = str(rule.get("source_candidate_id", ""))\n                candidate_row = self.db.query_one(\n                    "SELECT status FROM evolution_candidates WHERE candidate_id=?",\n                    (candidate_id,),\n                )\n                if candidate_row is None or candidate_row["status"] != "PROMOTED":\n                    continue\n                memory_id = str(memory.get("memory_id", ""))\n                effect = str(rule.get("effect", ""))\n                tool = str(rule.get("tool", ""))\n                if effect == "avoid_tool" and tool:\n                    candidates.append(\n                        HypothesisCandidate(\n                            key=f"memory_avoid_tool:{memory_id}:{tool}",\n                            subject=tool,\n                            claim=f"A promoted procedural memory requires avoiding {tool}.",\n                            rationale=(\n                                "A prior failure was experimentally recovered, human-promoted, "\n                                "and persisted as a high-confidence decision rule."\n                            ),\n                            base_score=0.88,\n                            actions=[\n                                self._noop(\n                                    f"Promoted procedural memory blocked {tool}", None\n                                )\n                            ],\n                            support_ids=[value for value in (memory_id, candidate_id) if value],\n                            memory_ids=[memory_id] if memory_id else [],\n                            cause_predicate="promoted_memory_rule",\n                        )\n                    )\n                elif effect == "replace_acceptance" and tool:\n                    acceptance = [str(value) for value in rule.get("acceptance", [])]\n                    if not acceptance:\n                        continue\n                    for original in list(candidates):\n                        matching = [\n                            action\n                            for action in original.actions\n                            if str(action.get("tool")) == tool\n                        ]\n                        if not matching:\n                            continue\n                        actions = [dict(action) for action in original.actions]\n                        for action in actions:\n                            if str(action.get("tool")) == tool:\n                                action["acceptance"] = acceptance\n                        candidates.append(\n                            HypothesisCandidate(\n                                key=f"memory_contract:{memory_id}:{original.key}",\n                                subject=original.subject,\n                                claim=(\n                                    f"A promoted procedural memory supplies the validated "\n                                    f"acceptance contract for {tool}."\n                                ),\n                                rationale=(\n                                    "The candidate preserves the grounded action but replaces "\n                                    "its failed contract with the human-promoted validated contract."\n                                ),\n                                base_score=max(0.82, original.base_score + 0.08),\n                                actions=actions,\n                                support_ids=list(\n                                    dict.fromkeys(\n                                        [*original.support_ids, memory_id, candidate_id]\n                                    )\n                                ),\n                                memory_ids=[memory_id] if memory_id else [],\n                                fact_ids=list(original.fact_ids),\n                                goal_id=original.goal_id,\n                                cause_predicate="promoted_memory_rule",\n                            )\n                        )\n\n        for skill in context.get("matching_skills", []):\n            if skill.get("status") not in {"APPROVED", "PROMOTED"} or not skill.get("steps"):\n                continue\n            skill_id = str(skill.get("skill_id"))\n            goal_id = self._best_goal_id(context, f"{skill.get(\'name\', \'\')} {skill.get(\'description\', \'\')}")\n            actions = []\n            for step in skill.get("steps", []):\n                actions.append({\n                    "tool": str(step["tool"]),\n                    "arguments": dict(step.get("arguments", {})),\n                    "purpose": f"[skill:{skill_id}] {step.get(\'purpose\', skill.get(\'description\', \'Run validated skill\'))}",\n                    "expected_result": str(step.get("expected_result", "Step completes under its tool contract")),\n                    "risk": str(skill.get("risk", "READ")),\n                    "goal_id": goal_id,\n                    "skill_id": skill_id,\n                    "acceptance": [str(value) for value in step.get("acceptance", [])],\n                })\n            candidates.append(HypothesisCandidate(\n                key=f"reuse_promoted_skill:{skill_id}", subject=str(skill.get("name", skill_id)),\n                claim="A validated promoted skill matches the present evidence.",\n                rationale="The skill lifecycle and match record provide a bounded reusable method.",\n                base_score=0.68 + 0.20 * float(skill.get("success_rate", 0.0)) + min(0.08, 0.01 * int(skill.get("use_count", 0))),\n                actions=actions, support_ids=[skill_id], goal_id=goal_id, cause_predicate="promoted_skill_match",\n            ))\n\n        for goal in context.get("goals", []):\n            title = str(goal.get("title", ""))\n            description = str(goal.get("description", ""))\n            goal_id = str(goal.get("goal_id", "")) or None\n            goal_target = self._extract_path(f"{title} {description}")\n            if goal_target and any(word in f"{title} {description}".lower() for word in ("inspect", "read", "list", "check")):\n                candidates.append(HypothesisCandidate(\n                    key=f"goal_path_inspection:{goal_id}:{goal_target}", subject=goal_target,\n                    claim="The active goal can advance through a bounded read-only path inspection.",\n                    rationale="The goal contains an inspection intent and a concrete path.",\n                    base_score=0.58 + 0.25 * float(goal.get("priority", 0.5)),\n                    actions=[self._action("list_directory", {"path": goal_target, "limit": 200}, f"Advance goal: {title}", "Bounded directory listing", ["output contains items"], goal_id)],\n                    support_ids=[goal_id] if goal_id else [], goal_id=goal_id, cause_predicate="active_goal",\n                ))\n\n        if context.get("unknowns"):\n            candidates.append(HypothesisCandidate(\n                key="preserve_explicit_unknowns", subject="world_model",\n                claim="Unresolved contradictions should remain explicit until new evidence arrives.",\n                rationale="Unknowns are evidence of uncertainty, not permission to invent a resolution.",\n                base_score=0.60, actions=[self._noop("Await disambiguating evidence", None)],\n                support_ids=[str(value) for value in context.get("unknowns", [])], cause_predicate="unresolved_contradiction",\n            ))\n        candidates.append(HypothesisCandidate(\n            key="deliberate_safe_noop", subject="runtime",\n            claim="No additional external action is justified.",\n            rationale="Safety and evidence thresholds prefer deliberate inactivity over fabricated work.",\n            base_score=0.35, actions=[self._noop("No supported action", None)], cause_predicate="insufficient_evidence",\n        ))\n        return candidates\n\n    def _score(self, candidate: HypothesisCandidate, context: dict[str, Any], *, include_memories: bool) -> float:\n        score = candidate.base_score\n        query = tokens(f"{candidate.subject} {candidate.claim} {candidate.rationale}")\n        if include_memories:\n            for memory in context.get("memories", []):\n                overlap = self._overlap(query, tokens(json.dumps(memory.get("content", {}), ensure_ascii=False, sort_keys=True)))\n                if overlap <= 0:\n                    continue\n                score += 0.22 * overlap * float(memory.get("importance", 0.5)) * float(memory.get("confidence", 0.5))\n                memory_id = str(memory.get("memory_id", ""))\n                if memory_id:\n                    candidate.memory_ids.append(memory_id)\n        for fact in context.get("world_facts", []):\n            overlap = self._overlap(query, tokens(f"{fact.get(\'subject\')} {fact.get(\'predicate\')} {fact.get(\'value\')}"))\n            if overlap <= 0:\n                continue\n            score += 0.12 * overlap * float(fact.get("confidence", 0.5))\n            fact_id = str(fact.get("fact_id", ""))\n            if fact_id:\n                candidate.fact_ids.append(fact_id)\n        for goal in context.get("goals", []):\n            overlap = self._overlap(query, tokens(f"{goal.get(\'title\')} {goal.get(\'description\')}"))\n            if overlap > 0:\n                score += 0.15 * overlap * float(goal.get("priority", 0.5))\n        penalty = 0.0\n        available = set(context.get("available_tools", []))\n        for action in candidate.actions:\n            penalty = max(penalty, {\n                RiskLevel.READ.value: 0.0,\n                RiskLevel.REVERSIBLE_WRITE.value: 0.12,\n                RiskLevel.HIGH.value: 0.35,\n                RiskLevel.IRREVERSIBLE.value: 0.80,\n            }.get(str(action.get("risk", "READ")), 0.40))\n            if action.get("tool") not in available:\n                penalty = max(penalty, 0.50)\n                candidate.opposing_ids.append(f"unavailable_tool:{action.get(\'tool\')}")\n        penalty *= 1.0 + 0.5 * float(context.get("affect", {}).get("safety_tension", 0.0))\n        return max(0.0, min(1.0, score - penalty))\n\n    def _create_predictions(self, trace_id: str, hypothesis_id: str, actions: list[dict[str, Any]], confidence: float, created_at: str) -> None:\n        with self.db.transaction() as connection:\n            for index, action in enumerate(actions):\n                connection.execute(\n                    """\n                    INSERT INTO cognitive_predictions(\n                        prediction_id,trace_id,hypothesis_id,action_index,expected_json,\n                        confidence,status,actual_json,created_at,resolved_at\n                    ) VALUES (?,?,?,?,?,?,\'OPEN\',NULL,?,NULL)\n                    """,\n                    (\n                        new_id("cogpred"), trace_id, hypothesis_id, index,\n                        json.dumps({"tool": action.get("tool"), "accepted": True, "acceptance": action.get("acceptance", [])}, ensure_ascii=False, sort_keys=True),\n                        confidence, created_at,\n                    ),\n                )\n\n    def _temporalize(self, candidate: HypothesisCandidate, cycle_id: str) -> dict[str, Any]:\n        source_ids = list(dict.fromkeys([*candidate.support_ids, cycle_id]))\n        entity_id = self.temporal_world.upsert_entity(\n            "cognitive_subject", candidate.subject, source_ids=source_ids,\n            attributes={"latest_claim": candidate.claim}, confidence=candidate.score,\n        )\n        cause_relation_id = self.temporal_world.assert_relation(\n            entity_id, candidate.cause_predicate, source_ids,\n            value=candidate.claim, epistemic_status="INFERRED", confidence=candidate.score,\n        )\n        tool = str(candidate.actions[0].get("tool")) if candidate.actions else "noop"\n        causal_hypothesis_id = self.temporal_world.add_causal_hypothesis(\n            candidate.cause_predicate, f"action:{tool}:accepted", source_ids,\n        )\n        return {\n            "entity_id": entity_id,\n            "cause_relation_id": cause_relation_id,\n            "causal_hypothesis_id": causal_hypothesis_id,\n            "effect_predicate": f"action:{tool}:accepted",\n        }\n\n    def _calibrate(self, trace: Any, successes: list[bool], plan: Plan, outcomes: list[dict[str, Any]]) -> dict[str, Any]:\n        if not successes:\n            return {"updated": False, "reason": "no observable action outcome"}\n        hypothesis = self.db.query_one(\n            "SELECT temporal_json FROM cognitive_hypotheses WHERE hypothesis_id=?",\n            (trace["selected_hypothesis_id"],),\n        )\n        if hypothesis is None:\n            return {"updated": False, "reason": "selected hypothesis missing"}\n        temporal = json.loads(hypothesis["temporal_json"])\n        if not temporal:\n            return {"updated": False, "reason": "temporal evidence unavailable"}\n        observed = all(successes)\n        source_ids = [str(item.get("action_id")) for item in outcomes if item.get("action_id")]\n        effect_relation_id = self.temporal_world.assert_relation(\n            temporal["entity_id"], temporal["effect_predicate"], source_ids or [plan.plan_id],\n            value=observed, epistemic_status="OBSERVED", confidence=1.0,\n        )\n        trial = self.temporal_world.record_causal_trial(\n            temporal["causal_hypothesis_id"], temporal["cause_relation_id"],\n            observed=observed, source_ids=source_ids or [plan.plan_id], effect_relation_id=effect_relation_id,\n        )\n        return {"updated": True, "observed": observed, "effect_relation_id": effect_relation_id, "causal_trial": trial}\n\n    @staticmethod\n    def _decomposition(candidate: HypothesisCandidate, actions: list[dict[str, Any]]) -> dict[str, Any]:\n        return {\n            "goal_id": candidate.goal_id,\n            "horizon": "receding",\n            "steps": [\n                {"stage": "EVIDENCE", "status": "CURRENT", "actions": [item.get("tool") for item in actions]},\n                {"stage": "PREDICT", "status": "OPEN", "criterion": "planned action satisfies its acceptance contract"},\n                {"stage": "REVISE", "status": "PENDING_OUTCOME", "criterion": "causal confidence updates from observed outcome"},\n                {"stage": "CONTINUE_OR_STOP", "status": "NEXT_CYCLE", "criterion": "new evidence must justify another bounded action"},\n            ],\n        }\n\n    @staticmethod\n    def _action(tool: str, arguments: dict[str, Any], purpose: str, expected_result: str, acceptance: list[str], goal_id: str | None) -> dict[str, Any]:\n        return {\n            "tool": tool,\n            "arguments": arguments,\n            "purpose": purpose,\n            "expected_result": expected_result,\n            "risk": RiskLevel.READ.value,\n            "goal_id": goal_id,\n            "skill_id": None,\n            "acceptance": acceptance,\n        }\n\n    @classmethod\n    def _noop(cls, reason: str, goal_id: str | None) -> dict[str, Any]:\n        return cls._action("noop", {"reason": reason}, "Record a deliberate no-op instead of inventing activity", "No external change", ["output ok is true"], goal_id)\n\n    @staticmethod\n    def _overlap(left: set[str], right: set[str]) -> float:\n        if not left or not right:\n            return 0.0\n        return len(left & right) / max(1, len(left | right))\n\n    @staticmethod\n    def _extract_path(text: str) -> str | None:\n        for pattern in (r"[A-Za-z]:[\\\\/][^\\s\\"\']+", r"(?:^|\\s)(/[^\\s\\"\']+)"):\n            match = re.search(pattern, text)\n            if match:\n                return (match.group(1) if match.lastindex else match.group(0)).strip()\n        return None\n\n    def _best_goal_id(self, context: dict[str, Any], text: str) -> str | None:\n        query = tokens(text)\n        best: tuple[float, str] | None = None\n        for goal in context.get("goals", []):\n            goal_id = str(goal.get("goal_id", ""))\n            if not goal_id:\n                continue\n            score = self._overlap(query, tokens(f"{goal.get(\'title\', \'\')} {goal.get(\'description\', \'\')}")) * float(goal.get("priority", 0.5))\n            if best is None or score > best[0]:\n                best = (score, goal_id)\n        return best[1] if best and best[0] > 0 else None\n\n    @staticmethod\n    def _digest_context(context: dict[str, Any]) -> dict[str, Any]:\n        return {\n            "cycle_id": context.get("cycle_id"),\n            "workspace": context.get("workspace", []),\n            "goals": context.get("goals", []),\n            "memory_ids": [item.get("memory_id") for item in context.get("memories", [])],\n            "world_fact_ids": [item.get("fact_id") for item in context.get("world_facts", [])],\n            "matching_skill_ids": [item.get("skill_id") for item in context.get("matching_skills", [])],\n            "drives": context.get("drives", {}),\n            "affect": context.get("affect", {}),\n            "budget": context.get("budget", {}),\n            "unknowns": context.get("unknowns", []),\n        }\n')
    write('source/src/wls/planner.py', 'from __future__ import annotations\n\nfrom abc import ABC, abstractmethod\nfrom pathlib import Path\nfrom typing import Any\nfrom urllib.error import HTTPError\nfrom urllib.parse import urlparse\nfrom urllib.request import HTTPRedirectHandler, Request, build_opener\nimport json\nimport os\n\nfrom .cognition import CognitiveEngine\nfrom .config import RuntimeConfig\nfrom .evidence import EvidenceLedger\nfrom .schemas import ActionSpec, Plan, RiskLevel\n\n\nclass NoRedirect(HTTPRedirectHandler):\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        raise HTTPError(req.full_url, code, "redirect blocked", headers, fp)\n\n\nclass PlanningProvider(ABC):\n    @abstractmethod\n    def create_plan(self, context: dict[str, Any]) -> dict[str, Any]:\n        raise NotImplementedError\n\n\nclass DeterministicProvider(PlanningProvider):\n    """Legacy grounded reflex planner retained as an explicit compatibility mode."""\n\n    TEXT_SUFFIXES = {\n        ".txt", ".md", ".json", ".yaml", ".yml", ".toml", ".py", ".js",\n        ".ts", ".ps1", ".bat", ".sh", ".ini", ".cfg", ".csv", ".log", ".tex",\n    }\n\n    def create_plan(self, context: dict[str, Any]) -> dict[str, Any]:\n        actions: list[dict[str, Any]] = []\n        max_actions = int(context["budget"].get("max_actions", 0))\n        outbox = Path(context["paths"]["outbox"])\n        for item in context.get("workspace", []):\n            if len(actions) >= max_actions:\n                break\n            if item.get("item_type") != "event":\n                continue\n            payload = item.get("payload", {})\n            observation = payload.get("payload", {}).get("observation", {})\n            kind = observation.get("kind")\n            subject = str(observation.get("subject", ""))\n            value = observation.get("value")\n            if kind == "filesystem_change" and value in {"created", "modified"}:\n                path = Path(subject)\n                if path.suffix.lower() in self.TEXT_SUFFIXES:\n                    actions.append(\n                        {\n                            "tool": "read_file",\n                            "arguments": {"path": subject, "max_bytes": 524288},\n                            "purpose": f"Inspect changed text file observed in {item[\'reference_id\']}",\n                            "expected_result": "File content or bounded binary preview",\n                            "risk": "READ",\n                            "goal_id": None,\n                            "skill_id": None,\n                            "acceptance": [\n                                "output contains path",\n                                "output contains text or binary marker",\n                            ],\n                        }\n                    )\n            elif kind in {"sensor_error", "service_health", "process_change"}:\n                note_path = outbox / f"attention-{item[\'reference_id\']}.json"\n                actions.append(\n                    {\n                        "tool": "emit_note",\n                        "arguments": {\n                            "path": str(note_path),\n                            "title": f"WLS attention: {kind}",\n                            "body": item.get("summary", "")[:4000],\n                        },\n                        "purpose": "Persist a bounded internal attention note for later human or connector review",\n                        "expected_result": "Internal note written to the WLS outbox",\n                        "risk": "READ",\n                        "goal_id": None,\n                        "skill_id": None,\n                        "acceptance": ["output contains path"],\n                    }\n                )\n            elif (\n                kind == "external_event"\n                and isinstance(value, dict)\n                and value.get("action") == "inspect_path"\n            ):\n                target_path = str(value.get("path", ""))\n                if target_path:\n                    actions.append(\n                        {\n                            "tool": "list_directory",\n                            "arguments": {"path": target_path, "limit": 200},\n                            "purpose": "Inspect a user-requested path without modifying it",\n                            "expected_result": "Bounded directory listing",\n                            "risk": "READ",\n                            "goal_id": None,\n                            "skill_id": None,\n                            "acceptance": ["output contains items"],\n                        }\n                    )\n        if not actions and max_actions > 0 and context.get("matching_skills"):\n            skill = context["matching_skills"][0]\n            if skill.get("status") in {"APPROVED", "PROMOTED"}:\n                for step in skill.get("steps", [])[:max_actions]:\n                    actions.append(\n                        {\n                            "tool": step["tool"],\n                            "arguments": dict(step.get("arguments", {})),\n                            "purpose": f"[skill:{skill[\'skill_id\']}] {step.get(\'purpose\', skill.get(\'description\', \'Run learned skill\'))}",\n                            "expected_result": "Step completes under its tool contract",\n                            "risk": skill.get("risk", "READ"),\n                            "goal_id": None,\n                            "skill_id": skill["skill_id"],\n                            "acceptance": list(step.get("acceptance", [])),\n                        }\n                    )\n        meaningful_workspace = any(\n            item.get("item_type") in {"event", "goal", "memory"}\n            for item in context.get("workspace", [])\n        )\n        if not actions and max_actions > 0 and meaningful_workspace:\n            actions.append(\n                {\n                    "tool": "noop",\n                    "arguments": {"reason": "No safe grounded external action was justified"},\n                    "purpose": "Record a deliberate no-op instead of inventing activity",\n                    "expected_result": "No external change",\n                    "risk": "READ",\n                    "goal_id": None,\n                    "skill_id": None,\n                    "acceptance": ["output ok is true"],\n                }\n            )\n        return {\n            "rationale": "Deterministic grounded plan derived only from current workspace items and configured budget.",\n            "actions": actions,\n            "memory_ids": [\n                item["reference_id"]\n                for item in context.get("workspace", [])\n                if item.get("item_type") == "memory"\n            ],\n            "world_fact_ids": [fact["fact_id"] for fact in context.get("world_facts", [])[:10]],\n            "unknowns": context.get("unknowns", []),\n        }\n\n\nclass CognitiveProvider(PlanningProvider):\n    """Standalone bounded local cognition backed by durable hypotheses and predictions."""\n\n    def __init__(self, cognition: CognitiveEngine):\n        self.cognition = cognition\n\n    def create_plan(self, context: dict[str, Any]) -> dict[str, Any]:\n        return self.cognition.create_plan(context)\n\n\nclass OpenAICompatibleProvider(PlanningProvider):\n    """Optional JSON planner using an OpenAI-compatible chat-completions endpoint."""\n\n    def __init__(self, settings: dict[str, Any]):\n        self.base_url = str(settings.get("base_url", "https://api.openai.com/v1")).rstrip("/")\n        parsed = urlparse(self.base_url)\n        if parsed.scheme not in {"http", "https"} or not parsed.hostname:\n            raise ValueError("invalid provider base_url")\n        if parsed.scheme != "https" and parsed.hostname not in {"127.0.0.1", "localhost", "::1"}:\n            raise ValueError("non-local provider endpoints require HTTPS")\n        self.model = str(settings.get("model", ""))\n        self.api_key_env = str(settings.get("api_key_env", "OPENAI_API_KEY"))\n        self.timeout = float(settings.get("timeout_seconds", 60.0))\n        if not self.model:\n            raise ValueError("provider model is required")\n\n    def create_plan(self, context: dict[str, Any]) -> dict[str, Any]:\n        api_key = os.environ.get(self.api_key_env)\n        if not api_key:\n            raise RuntimeError(f"missing API key environment variable: {self.api_key_env}")\n        system = (\n            "You are the bounded planner of a persistent local software-life runtime. "\n            "Use only facts, memories, skills, and tools in the supplied context. "\n            "Do not invent observations. Prefer no action over unsupported action. "\n            "Return one JSON object with keys rationale, actions, memory_ids, world_fact_ids, unknowns. "\n            "Every action must have tool, arguments, purpose, expected_result, risk, goal_id, skill_id, acceptance."\n        )\n        body = {\n            "model": self.model,\n            "messages": [\n                {"role": "system", "content": system},\n                {"role": "user", "content": json.dumps(context, ensure_ascii=False, sort_keys=True)},\n            ],\n            "temperature": 0,\n            "response_format": {"type": "json_object"},\n        }\n        request = Request(\n            f"{self.base_url}/chat/completions",\n            data=json.dumps(body).encode("utf-8"),\n            method="POST",\n            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},\n        )\n        opener = build_opener(NoRedirect)\n        with opener.open(request, timeout=self.timeout) as response:\n            raw = json.loads(response.read().decode("utf-8"))\n        content = raw["choices"][0]["message"]["content"]\n        return json.loads(content)\n\n\nclass FallbackProvider(PlanningProvider):\n    """Use a primary provider when available and record every bounded local fallback."""\n\n    def __init__(\n        self,\n        primary: PlanningProvider,\n        fallback: PlanningProvider,\n        ledger: EvidenceLedger,\n        primary_name: str,\n        fallback_name: str,\n    ) -> None:\n        self.primary = primary\n        self.fallback = fallback\n        self.ledger = ledger\n        self.primary_name = primary_name\n        self.fallback_name = fallback_name\n\n    def create_plan(self, context: dict[str, Any]) -> dict[str, Any]:\n        try:\n            return self.primary.create_plan(context)\n        except Exception as exc:\n            self.ledger.append(\n                "planning_provider_fallback",\n                {\n                    "cycle_id": context.get("cycle_id"),\n                    "primary": self.primary_name,\n                    "fallback": self.fallback_name,\n                    "error_type": type(exc).__name__,\n                    "error": str(exc)[:1000],\n                },\n            )\n            return self.fallback.create_plan(context)\n\n\nclass Planner:\n    def __init__(\n        self,\n        config: RuntimeConfig,\n        cognition: CognitiveEngine | None = None,\n        ledger: EvidenceLedger | None = None,\n    ):\n        provider_type = str(config.provider.get("type", "cognitive"))\n        self.provider_type = provider_type\n        if provider_type == "cognitive":\n            if cognition is None:\n                raise ValueError("cognitive provider requires CognitiveEngine")\n            self.provider: PlanningProvider = CognitiveProvider(cognition)\n        elif provider_type == "deterministic":\n            self.provider = DeterministicProvider()\n        elif provider_type == "openai_compatible":\n            primary = OpenAICompatibleProvider(config.provider)\n            fallback_name = str(config.provider.get("fallback", "cognitive"))\n            if fallback_name == "cognitive":\n                if cognition is None:\n                    raise ValueError("cognitive fallback requires CognitiveEngine")\n                fallback: PlanningProvider = CognitiveProvider(cognition)\n            elif fallback_name == "deterministic":\n                fallback = DeterministicProvider()\n            else:\n                raise ValueError(f"unknown provider fallback: {fallback_name}")\n            if ledger is None:\n                raise ValueError("provider fallback requires EvidenceLedger")\n            self.provider = FallbackProvider(\n                primary,\n                fallback,\n                ledger,\n                primary_name="openai_compatible",\n                fallback_name=fallback_name,\n            )\n        else:\n            raise ValueError(f"unknown provider type: {provider_type}")\n\n    def plan(self, context: dict[str, Any]) -> Plan:\n        raw = self.provider.create_plan(context)\n        if not isinstance(raw, dict):\n            raise ValueError("planner output must be an object")\n        required = {"rationale", "actions", "memory_ids", "world_fact_ids", "unknowns"}\n        if set(raw) - required:\n            raise ValueError(f"unexpected plan keys: {sorted(set(raw) - required)}")\n        if not isinstance(raw.get("rationale"), str):\n            raise ValueError("rationale must be a string")\n        if not isinstance(raw.get("actions"), list):\n            raise ValueError("actions must be a list")\n        actions: list[ActionSpec] = []\n        for index, item in enumerate(raw["actions"]):\n            if not isinstance(item, dict):\n                raise ValueError(f"action {index} must be an object")\n            expected_keys = {\n                "tool", "arguments", "purpose", "expected_result", "risk",\n                "goal_id", "skill_id", "acceptance",\n            }\n            extra = set(item) - expected_keys\n            if extra:\n                raise ValueError(f"unexpected action keys at {index}: {sorted(extra)}")\n            actions.append(\n                ActionSpec(\n                    tool=str(item["tool"]),\n                    arguments=dict(item.get("arguments", {})),\n                    purpose=str(item["purpose"]),\n                    expected_result=str(item["expected_result"]),\n                    risk=RiskLevel(str(item.get("risk", "READ"))),\n                    goal_id=item.get("goal_id"),\n                    skill_id=item.get("skill_id"),\n                    acceptance=[str(value) for value in item.get("acceptance", [])],\n                )\n            )\n        return Plan(\n            rationale=raw["rationale"],\n            actions=actions,\n            memory_ids=[str(value) for value in raw.get("memory_ids", [])],\n            world_fact_ids=[str(value) for value in raw.get("world_fact_ids", [])],\n            unknowns=[str(value) for value in raw.get("unknowns", [])],\n        )\n')
    write('source/tests/test_cognition.py', 'from __future__ import annotations\n\nfrom pathlib import Path\nimport os\n\nfrom wls.config import default_config\nfrom wls.runtime import LivingSystem\nfrom wls.schemas import (\n    EvidenceKind,\n    Goal,\n    MemoryItem,\n    Observation,\n    VerificationStatus,\n    new_id,\n    utc_now,\n)\n\n\ndef make_runtime(tmp_path: Path, *, provider: dict | None = None) -> LivingSystem:\n    config = default_config(tmp_path / "home")\n    config.sensors = []\n    config.max_actions_per_cycle = 4\n    config.sleep_after_idle_cycles = 100\n    if provider is not None:\n        config.provider = provider\n    return LivingSystem(config)\n\n\ndef ingest(runtime: LivingSystem, observation: Observation) -> str:\n    event_id, _ = runtime.events.add_observation(observation)\n    runtime.world.assimilate(observation)\n    return event_id\n\n\ndef test_default_runtime_uses_bounded_local_cognition(tmp_path: Path) -> None:\n    runtime = make_runtime(tmp_path)\n    assert runtime.config.provider["type"] == "cognitive"\n    assert runtime.planner.provider_type == "cognitive"\n    assert runtime.status()["cognition"]["traces"] == 0\n\n\ndef test_local_cognition_observes_predicts_acts_calibrates_and_survives_restart(\n    tmp_path: Path,\n) -> None:\n    runtime = make_runtime(tmp_path)\n    target = runtime.config.home_path / "sandbox" / "observed"\n    target.mkdir(parents=True)\n    (target / "evidence.txt").write_text("direct evidence", encoding="utf-8")\n    observation = Observation(\n        source="owner-test",\n        kind="external_event",\n        subject="owner-request",\n        predicate="request",\n        value={"action": "inspect_path", "path": str(target)},\n        confidence=1.0,\n        evidence_kind=EvidenceKind.DIRECT,\n        verification=VerificationStatus.VERIFIED,\n    )\n    ingest(runtime, observation)\n\n    result = runtime.run_cycle()\n\n    assert result["status"] == "SUCCEEDED"\n    assert result["cognition"] is not None\n    assert result["cognition"]["selected_key"].startswith("inspect_requested_path:")\n    assert result["cognition"]["predictions"][0]["status"] == "CONFIRMED"\n    assert result["cognition"]["calibration"]["updated"] is True\n    assert runtime.temporal_world.summary()["causal_trials"] == 1\n    assert runtime.cognition.integrity()[0] is True\n\n    restarted = LivingSystem(runtime.config)\n    traces = restarted.cognition.recent(limit=5)\n    assert traces[0]["status"] == "RESOLVED"\n    assert traces[0]["selected_key"].startswith("inspect_requested_path:")\n    assert restarted.temporal_world.summary()["causal_trials"] == 1\n    assert restarted.verify_integrity(full=True)["ok"] is True\n\n\ndef test_promoted_procedural_memory_changes_the_selected_behavior(tmp_path: Path) -> None:\n    runtime = make_runtime(tmp_path)\n    candidate_id = new_id("candidate")\n    now = utc_now()\n    runtime.db.execute(\n        """\n        INSERT INTO evolution_candidates(\n            candidate_id,candidate_type,title,proposal_json,source_ids_json,\n            baseline_json,experiment_json,result_json,status,created_at,updated_at\n        ) VALUES (?,?,?,?,?,?,?,?,?,?,?)\n        """,\n        (\n            candidate_id,\n            "recovery_rule",\n            "Avoid a repeatedly harmful note path",\n            "{}",\n            \'["test-source"]\',\n            "{}",\n            "{}",\n            "{}",\n            "PROMOTED",\n            now,\n            now,\n        ),\n    )\n    memory = MemoryItem(\n        memory_type="procedural",\n        content={\n            "decision_rule": {\n                "effect": "avoid_tool",\n                "tool": "emit_note",\n                "source_candidate_id": candidate_id,\n            },\n            "mechanism": "sensor error note path repeatedly amplified failure",\n        },\n        importance=1.0,\n        confidence=0.99,\n        source_ids=[candidate_id],\n        tags=["promoted_recovery", "decision_rule"],\n    )\n    memory_id = runtime.memories.add(memory)\n    retrieved = runtime.memories.retrieve("sensor error emit note", limit=8)\n    assert memory_id in {item["memory_id"] for item in retrieved}\n    observation = Observation(\n        source="sensor-test",\n        kind="sensor_error",\n        subject="sensor-test",\n        predicate="poll_status",\n        value="failed",\n        confidence=1.0,\n    )\n    event_id = ingest(runtime, observation)\n    event = runtime.db.query_one("SELECT * FROM events WHERE event_id=?", (event_id,))\n    assert event is not None\n    reserved = runtime.events.reserve(runtime.worker_id, 1)\n    context = {\n        "cycle_id": new_id("cycle"),\n        "workspace": runtime.attention.select(\n            reserved,\n            [],\n            retrieved,\n            *runtime.drives.load(),\n        ),\n        "goals": [],\n        "world_facts": runtime.world.active_facts(limit=20),\n        "memories": retrieved,\n        "matching_skills": [],\n        "self_model": runtime.self_model.snapshot(),\n        "relationships": runtime.relationships.snapshot(),\n        "drives": runtime.drives.load()[0].to_dict(),\n        "affect": runtime.drives.load()[1].to_dict(),\n        "budget": {"max_actions": 2},\n        "unknowns": [],\n        "available_tools": sorted(runtime.tools._tools),\n        "paths": {\n            "home": str(runtime.config.home_path),\n            "sandbox": str(runtime.config.sandbox_path),\n            "outbox": str(runtime.config.outbox_path),\n        },\n    }\n    context["workspace"] = [item.to_dict() for item in context["workspace"]]\n\n    plan = runtime.planner.plan(context)\n    trace = runtime.cognition.recent(limit=1)[0]\n\n    assert trace["counterfactual_key"].startswith("preserve_attention:")\n    assert trace["selected_key"].startswith("memory_avoid_tool:")\n    assert trace["memory_changed_decision"] is True\n    assert trace["memory_delta"] > 0\n    assert plan.actions[0].tool == "noop"\n    assert memory_id in plan.memory_ids\n\n\ndef test_unsupported_goal_produces_explicit_noop(tmp_path: Path) -> None:\n    runtime = make_runtime(tmp_path)\n    runtime.add_goal(\n        Goal(\n            title="Consider an unsupported possibility",\n            description="No target, evidence, or action authority is supplied.",\n            priority=0.6,\n            success_criteria=["uncertainty remains explicit"],\n        )\n    )\n\n    result = runtime.run_cycle()\n\n    assert result["status"] == "SUCCEEDED"\n    assert result["actions"] == 1\n    assert result["outcomes"][0]["success"] is True\n    action = runtime.db.query_one(\n        "SELECT tool,status FROM actions ORDER BY rowid DESC LIMIT 1"\n    )\n    assert action is not None\n    assert action["tool"] == "noop"\n    assert action["status"] == "SUCCEEDED"\n\n\ndef test_external_provider_failure_falls_back_to_local_cognition(\n    tmp_path: Path, monkeypatch,\n) -> None:\n    monkeypatch.delenv("WLS_TEST_MISSING_KEY", raising=False)\n    runtime = make_runtime(\n        tmp_path,\n        provider={\n            "type": "openai_compatible",\n            "base_url": "http://127.0.0.1:9/v1",\n            "model": "unavailable-test-model",\n            "api_key_env": "WLS_TEST_MISSING_KEY",\n            "fallback": "cognitive",\n        },\n    )\n    target = runtime.config.sandbox_path / "fallback-target"\n    target.mkdir(parents=True)\n    ingest(\n        runtime,\n        Observation(\n            source="owner-test",\n            kind="external_event",\n            subject="owner-request",\n            predicate="request",\n            value={"action": "inspect_path", "path": str(target)},\n        ),\n    )\n\n    result = runtime.run_cycle()\n\n    assert result["status"] == "SUCCEEDED"\n    assert result["cognition"] is not None\n    fallback = runtime.db.query_one(\n        "SELECT event_type,payload_json FROM evidence WHERE event_type=\'planning_provider_fallback\' ORDER BY seq DESC LIMIT 1"\n    )\n    assert fallback is not None\n    assert os.environ.get("WLS_TEST_MISSING_KEY") is None\n')
    write('source/scripts/verify_evolution_target_002.py', 'from __future__ import annotations\n\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nimport argparse\nimport json\n\nfrom wls.config import default_config\nfrom wls.runtime import LivingSystem\nfrom wls.schemas import EvidenceKind, Observation, VerificationStatus, utc_now\n\n\ndef run_probe() -> dict:\n    with TemporaryDirectory(prefix="wls-et002-") as raw:\n        root = Path(raw)\n        config = default_config(root / "home")\n        config.sensors = []\n        config.sleep_after_idle_cycles = 100\n        runtime = LivingSystem(config)\n        target = config.sandbox_path / "world"\n        target.mkdir(parents=True)\n        (target / "evidence.txt").write_text("observed", encoding="utf-8")\n        observation = Observation(\n            source="et002-verifier",\n            kind="external_event",\n            subject="owner-request",\n            predicate="request",\n            value={"action": "inspect_path", "path": str(target)},\n            confidence=1.0,\n            evidence_kind=EvidenceKind.DIRECT,\n            verification=VerificationStatus.VERIFIED,\n        )\n        runtime.events.add_observation(observation)\n        runtime.world.assimilate(observation)\n        result = runtime.run_cycle()\n        restarted = LivingSystem(config)\n        trace = restarted.cognition.recent(limit=1)[0]\n        cognition_ok, cognition_details = restarted.cognition.integrity()\n        integrity = restarted.verify_integrity(full=True)\n        temporal = restarted.temporal_world.summary()\n        checks = {\n            "cycle_succeeded": result["status"] == "SUCCEEDED",\n            "bounded_cognition_selected_request": trace["selected_key"].startswith(\n                "inspect_requested_path:"\n            ),\n            "prediction_confirmed": (\n                trace["outcome"]["predictions"][0]["status"] == "CONFIRMED"\n            ),\n            "causal_trial_persisted": temporal["causal_trials"] >= 1,\n            "trace_survived_restart": trace["status"] == "RESOLVED",\n            "cognition_integrity": cognition_ok,\n            "runtime_integrity": integrity["ok"],\n        }\n        return {\n            "target": "EVOLUTION-TARGET-002",\n            "generated_at": utc_now(),\n            "passed": all(checks.values()),\n            "checks": checks,\n            "cycle": {\n                "status": result["status"],\n                "plan_status": result["plan_status"],\n                "actions": result["actions"],\n                "outcomes": result["outcomes"],\n            },\n            "trace": trace,\n            "temporal_world": temporal,\n            "cognition_integrity": cognition_details,\n            "runtime_integrity": integrity,\n            "claim_boundary": (\n                "This verifies a bounded local cognition vertical slice with durable "\n                "hypothesis competition, prediction, action, calibration, and restart "\n                "continuity. It does not prove general intelligence, consciousness, or "\n                "long-term autonomous superiority."\n            ),\n        }\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--output")\n    args = parser.parse_args()\n    report = run_probe()\n    rendered = json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True)\n    if args.output:\n        output = Path(args.output)\n        output.parent.mkdir(parents=True, exist_ok=True)\n        output.write_text(rendered + "\\n", encoding="utf-8")\n    print(rendered)\n    return 0 if report["passed"] else 2\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n')
    replace_once('source/src/wls/config.py', '    provider: dict[str, Any] = field(default_factory=lambda: {"type": "deterministic"})\n', '    provider: dict[str, Any] = field(\n        default_factory=lambda: {"type": "cognitive", "fallback": "deterministic"}\n    )\n')
    replace_once('source/src/wls/config.py', '            if sensor.interval_seconds <= 0:\n                raise ValueError(f"sensor interval must be positive: {sensor.name}")\n\n    def ensure_directories(self) -> None:\n', '            if sensor.interval_seconds <= 0:\n                raise ValueError(f"sensor interval must be positive: {sensor.name}")\n        provider_type = str(self.provider.get("type", "cognitive"))\n        if provider_type not in {"cognitive", "deterministic", "openai_compatible"}:\n            raise ValueError(f"unknown provider type: {provider_type}")\n        cognitive_min_confidence = float(\n            self.provider.get("cognitive_min_confidence", 0.52)\n        )\n        if not 0.0 <= cognitive_min_confidence <= 1.0:\n            raise ValueError("cognitive_min_confidence must be within [0, 1]")\n        cognitive_max_hypotheses = int(\n            self.provider.get("cognitive_max_hypotheses", 6)\n        )\n        if not 2 <= cognitive_max_hypotheses <= 20:\n            raise ValueError("cognitive_max_hypotheses must be within 2..20")\n        if provider_type == "openai_compatible":\n            fallback = str(self.provider.get("fallback", "cognitive"))\n            if fallback not in {"cognitive", "deterministic"}:\n                raise ValueError(f"unknown provider fallback: {fallback}")\n\n    def ensure_directories(self) -> None:\n')
    replace_once('source/src/wls/runtime.py', 'from .config import RuntimeConfig, load_or_create_config\n', 'from .cognition import CognitiveEngine\nfrom .config import RuntimeConfig, load_or_create_config\n')
    replace_once('source/src/wls/runtime.py', 'from .tools import ToolRegistry\nfrom .world import WorldModel\n', 'from .temporal_world import TemporalCausalWorld\nfrom .tools import ToolRegistry\nfrom .world import WorldModel\n')
    replace_once('source/src/wls/runtime.py', '        self.world = WorldModel(self.db, self.ledger)\n        self.drives = DriveSystem(self.db, self.ledger)\n', '        self.world = WorldModel(self.db, self.ledger)\n        self.temporal_world = TemporalCausalWorld(self.db, self.ledger)\n        self.drives = DriveSystem(self.db, self.ledger)\n')
    replace_once('source/src/wls/runtime.py', '        self.attention = AttentionSystem(config.workspace_capacity)\n        self.planner = Planner(config)\n        self.growth = GrowthCycleManager(self)\n', '        self.attention = AttentionSystem(config.workspace_capacity)\n        self.cognition = CognitiveEngine(\n            self.db, self.ledger, self.temporal_world, config\n        )\n        self.planner = Planner(config, self.cognition, self.ledger)\n        self.growth = GrowthCycleManager(self)\n')
    replace_once('source/src/wls/runtime.py', '                self._persist_plan_and_ack_events(\n                    cycle_id, plan, [event.event_id for event in selected_events]\n                )\n                plan_persisted = True\n                outcomes = [*recovery_outcomes, *self._execute_plan(plan)]\n                plan_status = self._plan_status(plan.plan_id)\n', '                self._persist_plan_and_ack_events(\n                    cycle_id, plan, [event.event_id for event in selected_events]\n                )\n                self.cognition.attach_plan(cycle_id, plan)\n                plan_persisted = True\n                outcomes = [*recovery_outcomes, *self._execute_plan(plan)]\n                cognition_result = self.cognition.resolve_cycle(cycle_id, plan, outcomes)\n                plan_status = self._plan_status(plan.plan_id)\n')
    replace_once('source/src/wls/runtime.py', '                outcomes = []\n                plan_status = "IDLE"\n                episode_id = None\n                post_appraisal = {"idle": True}\n', '                outcomes = []\n                cognition_result = None\n                plan_status = "IDLE"\n                episode_id = None\n                post_appraisal = {"idle": True}\n')
    replace_once('source/src/wls/runtime.py', '                "plan_status": plan_status,\n                "appraisal": appraisal,\n', '                "plan_status": plan_status,\n                "cognition": cognition_result,\n                "appraisal": appraisal,\n')
    replace_once('source/src/wls/runtime.py', '            "active_skills": self.skills.active(),\n            "growth_cycles": self.growth.summary(limit=20),\n            "next_focus": self.db.get_runtime("next_focus", []),\n', '            "active_skills": self.skills.active(),\n            "growth_cycles": self.growth.summary(limit=20),\n            "planner_provider": self.planner.provider_type,\n            "cognition": self.cognition.summary(limit=500),\n            "temporal_world": self.temporal_world.summary(),\n            "next_focus": self.db.get_runtime("next_focus", []),\n')
    replace_once('source/src/wls/runtime.py', '        result = {\n            "ok": ledger_ok and db_ok,\n            "ledger": ledger_details,\n            "database": db_details,\n        }\n', '        cognition_ok, cognition_details = self.cognition.integrity()\n        result = {\n            "ok": ledger_ok and db_ok and cognition_ok,\n            "ledger": ledger_details,\n            "database": db_details,\n            "cognition": cognition_details,\n        }\n')
    replace_once('source/src/wls/cli.py', '    growth_status = sub.add_parser("growth-status", help="Show growth-cycle evidence")\n    growth_status.add_argument("--limit", type=int, default=20)\n\n    export = sub.add_parser("export-evidence")\n', '    growth_status = sub.add_parser("growth-status", help="Show growth-cycle evidence")\n    growth_status.add_argument("--limit", type=int, default=20)\n\n    cognition = sub.add_parser(\n        "cognition", help="Show durable local hypotheses, predictions, and calibration"\n    )\n    cognition.add_argument("--limit", type=int, default=20)\n\n    export = sub.add_parser("export-evidence")\n')
    replace_once('source/src/wls/cli.py', '        elif args.command == "growth-status":\n            print_json(runtime.growth.summary(limit=args.limit))\n        elif args.command == "export-evidence":\n', '        elif args.command == "growth-status":\n            print_json(runtime.growth.summary(limit=args.limit))\n        elif args.command == "cognition":\n            print_json(\n                {\n                    "summary": runtime.cognition.summary(limit=500),\n                    "recent": runtime.cognition.recent(limit=args.limit),\n                    "temporal_world": runtime.temporal_world.summary(),\n                }\n            )\n        elif args.command == "export-evidence":\n')
    replace_once('source/src/wls/_version.py', '__version__ = "0.7.0.dev1"', '__version__ = "0.8.0.dev1"')
    replace_once('source/pyproject.toml', 'version = "0.7.0.dev1"', 'version = "0.8.0.dev1"')
    section = '## EVOLUTION-TARGET-002: bounded local cognition\n\nThe default standalone planner is now `cognitive`. It performs local evidence-bound\nhypothesis competition, records alternatives and a memory-free counterfactual, creates\nexplicit action predictions, resolves them from real tool outcomes, and calibrates causal\nconfidence in the existing temporal world model. External OpenAI-compatible planners are\noptional and fall back to this local cognition path when unavailable.\n\n```bash\nwls --config CONFIG cognition --limit 20\n```\n\nThis is a bounded engineering cognition layer, not a claim of AGI, subjective\nconsciousness, or unrestricted autonomous reasoning.\n'
    append_once("README.md", "## EVOLUTION-TARGET-002: bounded local cognition", section)
    append_once("source/README.md", "## EVOLUTION-TARGET-002: bounded local cognition", section)
    state = ROOT / "CURRENT_STATE.yaml"
    text = state.read_text(encoding="utf-8")
    text = text.replace('development_version: "0.7.0.dev1"', 'development_version: "0.8.0.dev1"', 1)
    text = text.replace('schema_version: "1.2"', 'schema_version: "1.3"', 1)
    text = text.replace('update_type: "canonical-growth-merged"', 'update_type: "bounded-local-cognition-candidate"', 1)
    if "active_iteration_candidate:" not in text:
        text = text.rstrip() + '\n\nactive_iteration_candidate:\n  id: "EVOLUTION-TARGET-002"\n  title: "Bounded local cognition vertical slice"\n  status: "IMPLEMENTED_PENDING_CI_AND_MERGE"\n  objective: >-\n    Integrate the existing temporal causal world model into the canonical LivingSystem,\n    replace the default hard-coded reflex planner with durable local hypothesis\n    competition, preserve memory-free counterfactuals, generate explicit predictions,\n    and calibrate them from real tool outcomes without requiring an external model.\n  claim_boundary: >-\n    This target can establish bounded local cognition behavior only. It cannot establish\n    AGI, subjective consciousness, unrestricted autonomy, or long-term superiority.\n'
